     2→
     3→import (
     4→	"context"
     5→	"fmt"
     6→
     7→	"github.com/OffchainLabs/prysm/v6/beacon-chain/core/helpers"
     8→	"github.com/OffchainLabs/prysm/v6/beacon-chain/core/signing"
     9→	"github.com/OffchainLabs/prysm/v6/beacon-chain/core/transition"
    10→	forkchoicetypes "github.com/OffchainLabs/prysm/v6/beacon-chain/forkchoice/types"
    11→	"github.com/OffchainLabs/prysm/v6/beacon-chain/state"
    12→	lruwrpr "github.com/OffchainLabs/prysm/v6/cache/lru"
    13→	"github.com/OffchainLabs/prysm/v6/config/params"
    14→	"github.com/OffchainLabs/prysm/v6/consensus-types/primitives"
    15→	"github.com/OffchainLabs/prysm/v6/crypto/bls"
    16→	ethpb "github.com/OffchainLabs/prysm/v6/proto/prysm/v1alpha1"
    17→	"github.com/OffchainLabs/prysm/v6/time/slots"
    18→	lru "github.com/hashicorp/golang-lru"
    19→	"github.com/sirupsen/logrus"
    20→)
    21→
    22→const (
    23→	defaultSignatureCacheSize      = 256
    24→	defaultInclusionProofCacheSize = 2
    25→)
    26→
    27→// validatorAtIndexer defines the method needed to retrieve a validator by its index.
    28→// This interface is satisfied by state.BeaconState, but can also be satisfied by a cache.
    29→type validatorAtIndexer interface {
    30→	ValidatorAtIndex(idx primitives.ValidatorIndex) (*ethpb.Validator, error)
    31→}
    32→
    33→// signatureCache represents a type that can perform signature verification and cache the result so that it
    34→// can be used when the same signature is seen in multiple places, like a SignedBeaconBlockHeader
    35→// found in multiple BlobSidecars.
    36→type signatureCache interface {
    37→	// VerifySignature perform signature verification and caches the result.
    38→	VerifySignature(sig signatureData, v validatorAtIndexer) (err error)
    39→	// SignatureVerified accesses the result of a previous signature verification.
    40→	SignatureVerified(sig signatureData) (bool, error)
    41→}
    42→
    43→// signatureData represents the set of parameters that together uniquely identify a signature observed on
    44→// a beacon block. This is used as the key for the signature cache.
    45→type signatureData struct {
    46→	Root      [32]byte
    47→	Parent    [32]byte
    48→	Signature [96]byte
    49→	Proposer  primitives.ValidatorIndex
    50→	Slot      primitives.Slot
    51→}
    52→
    53→func (d signatureData) logFields() logrus.Fields {
    54→	return logrus.Fields{
    55→		"root":       fmt.Sprintf("%#x", d.Root),
    56→		"parentRoot": fmt.Sprintf("%#x", d.Parent),
    57→		"signature":  fmt.Sprintf("%#x", d.Signature),
    58→		"proposer":   d.Proposer,
    59→		"slot":       d.Slot,
    60→	}
    61→}
    62→
    63→func newSigCache(vr []byte, size int, gf forkLookup) *sigCache {
    64→	if gf == nil {
    65→		gf = params.Fork
    66→	}
    67→	return &sigCache{Cache: lruwrpr.New(size), valRoot: vr, getFork: gf}
    68→}
    69→
    70→type sigCache struct {
    71→	*lru.Cache
    72→	valRoot []byte
    73→	getFork forkLookup
    74→}
    75→
    76→type inclusionProofCache struct {
    77→	*lru.Cache
    78→}
    79→
    80→func newInclusionProofCache(size int) *inclusionProofCache {
    81→	return &inclusionProofCache{Cache: lruwrpr.New(size)}
    82→}
    83→
    84→// VerifySignature verifies the given signature data against the key obtained via validatorAtIndexer.
    85→func (c *sigCache) VerifySignature(sig signatureData, v validatorAtIndexer) (err error) {
    86→	defer func() {
    87→		if err == nil {
    88→			c.Add(sig, true)
    89→		} else {
    90→			log.WithError(err).WithFields(sig.logFields()).Debug("Caching failed signature verification result")
    91→			c.Add(sig, false)
    92→		}
    93→	}()
    94→	e := slots.ToEpoch(sig.Slot)
    95→	fork, err := c.getFork(e)
    96→	if err != nil {
    97→		return err
    98→	}
    99→	domain, err := signing.Domain(fork, e, params.BeaconConfig().DomainBeaconProposer, c.valRoot)
   100→	if err != nil {
   101→		return err
   102→	}
   103→	pv, err := v.ValidatorAtIndex(sig.Proposer)
   104→	if err != nil {
   105→		return err
   106→	}
   107→	pb, err := bls.PublicKeyFromBytes(pv.PublicKey)
   108→	if err != nil {
   109→		return err
   110→	}
   111→	s, err := bls.SignatureFromBytes(sig.Signature[:])
   112→	if err != nil {
   113→		return err
   114→	}
   115→	sr, err := signing.ComputeSigningRootForRoot(sig.Root, domain)
   116→	if err != nil {
   117→		return err
   118→	}
   119→	if !s.Verify(pb, sr[:]) {
   120→		return signing.ErrSigFailedToVerify
   121→	}
   122→
   123→	return nil
   124→}
   125→
   126→// SignatureVerified checks the signature cache for the given key, and returns a boolean value of true
   127→// if it has been seen before, and an error value indicating whether the signature verification succeeded.
   128→// ie only a result of (true, nil) means a previous signature check passed.
   129→func (c *sigCache) SignatureVerified(sig signatureData) (bool, error) {
   130→	val, seen := c.Get(sig)
   131→	if !seen {
   132→		return false, nil
   133→	}
   134→	verified, ok := val.(bool)
   135→	if !ok {
   136→		log.WithFields(sig.logFields()).Debug("Ignoring invalid value found in signature cache")
   137→		// This shouldn't happen, and if it does, the caller should treat it as a cache miss and run verification
   138→		// again to correctly populate the cache key.
   139→		return false, nil
   140→	}
   141→	if verified {
   142→		return true, nil
   143→	}
   144→	return true, signing.ErrSigFailedToVerify
   145→}
   146→
   147→// proposerCache represents a type that can compute the proposer for a given slot + parent root,
   148→// and cache the result so that it can be reused when the same verification needs to be performed
   149→// across multiple values.
   150→type proposerCache interface {
   151→	ComputeProposer(ctx context.Context, root [32]byte, slot primitives.Slot, pst state.BeaconState) (primitives.ValidatorIndex, error)
   152→	Proposer(c *forkchoicetypes.Checkpoint, slot primitives.Slot) (primitives.ValidatorIndex, bool)
   153→}
   154→
   155→func newPropCache() *propCache {
   156→	return &propCache{}
   157→}
   158→
   159→type propCache struct {
   160→}
   161→
   162→// ComputeProposer takes the state for the given parent root and slot and computes the proposer index, updating the
   163→// proposer index cache when successful.
   164→func (*propCache) ComputeProposer(ctx context.Context, parent [32]byte, slot primitives.Slot, pst state.BeaconState) (primitives.ValidatorIndex, error) {
   165→	pst, err := transition.ProcessSlotsUsingNextSlotCache(ctx, pst, parent[:], slot)
   166→	if err != nil {
   167→		return 0, err
   168→	}
   169→	idx, err := helpers.BeaconProposerIndex(ctx, pst)
   170→	if err != nil {
   171→		return 0, err
   172→	}
   173→	return idx, nil
   174→}
   175→
   176→// Proposer returns the validator index if it is found in the cache, along with a boolean indicating
